def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 - x^2y^2z^2 = 0"""
    return x**3 + y**3 + z**3 == x**2 * y**2 * z**2

solutions = []
limit = 4

# Iterate through all triples (x, y, z) such that 1 <= x <= y <= z <= 4
for x in range(1, limit + 1):
    for y in range(x, limit + 1):
        for z in range(y, limit + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print(f"Solutions found: {solutions}")

